.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel List (Left Sidebar) */
::deep .channel-list {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .channel-list-header {
    padding: 0 1rem;
