+    flex-shrink: 0;
+}
+
+::deep .message-input,
+::deep .thread-input {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1rem;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 2.5rem;
+    max-height: 8rem;
+    font-family: inherit;
+}
+
+::deep .message-input:focus,
+::deep .thread-input:focus {
+    outline: none;
+    box-shadow: 0 0 0 2px #5865f2;
+}
+
+::deep .send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1.2rem;
+    font-size: 0.85rem;
+    font-weight: 600;
+    cursor: pointer;
+    align-self: flex-end;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel (Right Side) */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 250px;
+    background: #2b2d31;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #1e1f22;
+    height: 100%;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    flex-shrink: 0;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.25rem;
+    border-radius: 3px;
+}
+
+::deep .close-btn:hover {
+    background: #404249;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    background: #2e3035;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+}
+

